$reviewed_links$::jsonb;
 item record;
 columns_found text[];
 failures integer;
 inserted_count integer;
BEGIN
 PERFORM set_config('lock_timeout','10s',true);
 PERFORM pg_advisory_xact_lock(hashtext('rpg_all_standards_reviewed_links_20261028'));
 LOCK TABLE public.internal_audit_standard_catalogue IN SHARE MODE;
 LOCK TABLE public.internal_audit_questions IN SHARE MODE;
 LOCK TABLE public.assessment_questions IN SHARE MODE;
 LOCK TABLE public.internal_audit_question_scope_links IN SHARE ROW EXCLUSIVE MODE;

 -- Require the confirmed, corrected unique key, without altering it again.
 SELECT array_agg(a.attname::text ORDER BY k.position) INTO columns_found
 FROM pg_constraint c
 CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS k(column_number,position)
 JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.column_number
 WHERE c.conrelid='public.internal_audit_question_scope_links'::regclass
  AND c.conname='internal_audit_question_scope_question_id_standard_id_scope_key'
  AND c.contype='u';
 IF columns_found IS DISTINCT FROM ARRAY['question_id','standard_id','scope_key','clause']::text[] THEN
  RAISE EXCEPTION 'Install corrected File 13 first: the scope-link unique key must include clause. No changes saved.';
 END IF;

 FOR item IN SELECT DISTINCT standard_id,standard_code,expected_display_name,expected_edition_label FROM jsonb_to_recordset(v_reviewed_links) AS r(standard_id uuid,standard_code text,question_id uuid,question_standard_id uuid,
 question_code text,question_clause text,question_digest text,scope_key text,
 clause text,reference_id uuid,reference_bank text,reference_digest text,
 match_kind text,expected_display_name text,expected_edition_label text,question_source_edition text) LOOP
  SELECT count(*) INTO failures FROM public.internal_audit_standard_catalogue
   WHERE standard_code=item.standard_code AND active IS TRUE;
  IF failures<>1 OR NOT EXISTS(SELECT 1 FROM public.internal_audit_standard_catalogue
   WHERE id=item.standard_id AND standard_code=item.standard_code AND active IS TRUE
    AND display_name=item.expected_display_name AND edition_label=item.expected_edition_label) THEN
   RAISE EXCEPTION 'Catalogue % is missing, inactive, changed or duplicated. No changes saved.',item.standard_code;
  END IF;
 END LOOP;

 -- Every question identity, edition, clause and text is pinned to the supplied
 -- diagnostic. A changed/retired source needs review, never automatic guessing.
 SELECT count(*) INTO failures FROM jsonb_to_recordset(v_reviewed_links) AS r(standard_id uuid,standard_code text,question_id uuid,question_standard_id uuid,
 question_code text,question_clause text,question_digest text,scope_key text,
 clause text,reference_id uuid,reference_bank text,reference_digest text,
 match_kind text,expected_display_name text,expected_edition_label text,question_source_edition text)
 LEFT JOIN public.internal_audit_questions q ON q.id=r.question_id
 WHERE q.id IS NULL OR q.active IS DISTINCT FROM TRUE
  OR q.standard_id IS DISTINCT FROM r.question_standard_id
  OR q.source_edition IS DISTINCT FROM r.question_source_edition
  OR q.question_code IS DISTINCT FROM r.question_code
  OR q.clause IS DISTINCT FROM r.question_clause
  OR md5(coalesce(q.question_text,''))<>r.question_digest;
 IF failures>0 THEN
  RAISE EXCEPTION '% reviewed mappings have a missing, retired or changed source question. All changes rolled back; refresh the diagnostic.',failures;
 END IF;

 SELECT count(*) INTO failures FROM jsonb_to_recordset(v_reviewed_links) AS r(standard_id uuid,standard_code text,question_id uuid,question_standard_id uuid,
 question_code text,question_clause text,question_digest text,scope_key text,
 clause text,reference_id uuid,reference_bank text,reference_digest text,
 match_kind text,expected_display_name text,expected_edition_label text,question_source_edition text)
 LEFT JOIN public.assessment_questions a ON a.id=r.reference_id
 WHERE r.reference_id IS NOT NULL AND
  (a.id IS NULL OR a.active IS DISTINCT FROM TRUE
   OR a.standard IS DISTINCT FROM r.reference_bank
   OR coalesce(nullif(trim(a.clause_reference),''),a.question_number) IS DISTINCT FROM r.clause
   OR md5(coalesce(a.question,''))<>r.reference_digest
   OR nullif(trim(a.requirement_summary),'') IS NULL
   OR nullif(trim(a.objective_evidence),'') IS NULL);
 IF failures>0 THEN
  RAISE EXCEPTION '% controlled references are missing, retired, changed or incomplete. All changes rolled back; review current references.',failures;
 END IF;

 -- Cross-catalogue reuse is limited to the confirmed two 17025:2017 entries.
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(v_reviewed_links) AS r(standard_id uuid,standard_code text,question_id uuid,question_standard_id uuid,
 question_code text,question_clause text,question_digest text,scope_key text,
 clause text,reference_id uuid,reference_bank text,reference_digest text,
 match_kind text,expected_display_name text,expected_edition_label text,question_source_edition text)
  JOIN public.internal_audit_standard_catalogue source ON source.id=r.question_standard_id
  JOIN public.internal_audit_standard_catalogue target ON target.id=r.standard_id
  WHERE r.question_standard_id<>r.standard_id AND
   (source.standard_code IS DISTINCT FROM 'ISO/IEC 17025:2017'
    OR source.edition_label IS DISTINCT FROM '2017'
    OR target.standard_code IS DISTINCT FROM 'ISO/IEC 17025'
    OR target.edition_label IS DISTINCT FROM '2017'
    OR r.match_kind<>'same_edition_shared_existing_question')) THEN
  RAISE EXCEPTION 'A cross-catalogue mapping does not match the reviewed 17025:2017 editions. No changes saved.';
 END IF;

 -- Identical-text links additionally prove the precise native question's
 -- relationship to the referenced Assessment record.
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(v_reviewed_links) AS r(standard_id uuid,standard_code text,question_id uuid,question_standard_id uuid,
 question_code text,question_clause text,question_digest text,scope_key text,
 clause text,reference_id uuid,reference_bank text,reference_digest text,
 match_kind text,expected_display_name text,expected_edition_label text,question_source_edition text)
  JOIN public.internal_audit_questions q ON q.id=r.question_id
  JOIN public.assessment_questions a ON a.id=r.reference_id
  WHERE r.match_kind IN ('identical_existing_controlled_text','same_edition_shared_existing_question')
   AND lower(regexp_replace(trim(q.question_text),'[[:space:]]+',' ','g'))
    <>lower(regexp_replace(trim(a.question),'[[:space:]]+',' ','g'))) THEN
  RAISE EXCEPTION 'An exact controlled-text association no longer matches. No changes saved.';
 END IF;

 INSERT INTO public.internal_audit_question_scope_links
  (question_id,standard_id,scope_key,clause,requirement_summary)
 SELECT r.question_id,r.standard_id,r.scope_key,r.clause,
  CASE WHEN r.reference_id IS NOT NULL THEN concat_ws(E'\n',
   'Requirement: '||nullif(trim(a.requirement_summary),''),
   'Audit test: '||nullif(trim(a.question),''),
   'Objective evidence: '||nullif(trim(a.objective_evidence),''))
  ELSE concat_ws(E'\n',
   'Audit test: '||q.question_text,
   'Requirement: '||nullif(trim(q.requirement_summary),''),
   'Objective evidence: '||nullif(trim(q.evidence_examples),'')) END
 FROM jsonb_to_recordset(v_reviewed_links) AS r(standard_id uuid,standard_code text,question_id uuid,question_standard_id uuid,
 question_code text,question_clause text,question_digest text,scope_key text,
 clause text,reference_id uuid,reference_bank text,reference_digest text,
 match_kind text,expected_display_name text,expected_edition_label text,question_source_edition text)
 JOIN public.internal_audit_questions q ON q.id=r.question_id
 LEFT JOIN public.assessment_questions a ON a.id=r.reference_id
 WHERE NOT EXISTS(SELECT 1 FROM public.internal_audit_question_scope_links existing
  WHERE existing.question_id=r.question_id AND existing.standard_id=r.standard_id
   AND existing.scope_key=r.scope_key AND existing.clause=r.clause)
 ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS inserted_count = ROW_COUNT;

 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(v_reviewed_links) AS r(standard_id uuid,standard_code text,question_id uuid,question_standard_id uuid,
 question_code text,question_clause text,question_digest text,scope_key text,
 clause text,reference_id uuid,reference_bank text,reference_digest text,
 match_kind text,expected_display_name text,expected_edition_label text,question_source_edition text)
  WHERE NOT EXISTS(SELECT 1 FROM public.internal_audit_question_scope_links l
   WHERE l.question_id=r.question_id AND l.standard_id=r.standard_id
    AND l.scope_key=r.scope_key AND l.clause=r.clause)) THEN
  RAISE EXCEPTION 'An existing database constraint prevented a reviewed scope link. All changes rolled back; inspect mapping constraints.';
 END IF;
 RAISE NOTICE 'Reviewed scope-link repair completed: % links added; existing records preserved. Verify current Fieldwork coverage.',inserted_count;
END;
$rpg_coverage_repair$;

-- This is a mapping-application result, NOT an audit completion certificate.
-- The application performs range/point parsing, selected-scope/exclusion and
-- answer/evidence checks; SQL must not substitute a weaker coverage percentage.
WITH banks(standard_code,expected_bank,base_amendment_review) AS (VALUES
 ('AS9100','AS9100 Rev D',false),
 ('ISO 14001','ISO 14001:2026',false),
 ('ISO 19011','ISO 19011:2026',false),
 ('ISO 22301','ISO 22301:2019',true),
 ('ISO 45001','ISO 45001:2018',true),
 ('ISO 9001','ISO 9001:2015/Amd 1:2024',false),
 ('ISO 9001:2026','ISO 9001:2026',false),
 ('ISO/IEC 17024','ISO/IEC 17024:2026',false),
 ('ISO/IEC 17025','ISO/IEC 17025:2017',false),
 ('ISO/IEC 17025:2017','ISO/IEC 17025:2017',false),
 ('ISO/IEC 27001','ISO/IEC 27001:2022',true)
)
SELECT s.standard_code,
 (SELECT count(*) FROM public.internal_audit_questions q WHERE q.standard_id=s.id AND q.active IS TRUE) AS active_native_questions,
 (SELECT count(DISTINCT l.question_id) FROM public.internal_audit_question_scope_links l
   JOIN public.internal_audit_questions q ON q.id=l.question_id AND q.active IS TRUE
   WHERE l.standard_id=s.id) AS mapped_active_questions,
 (SELECT count(*) FROM public.internal_audit_question_scope_links l
   LEFT JOIN public.internal_audit_questions q ON q.id=l.question_id
   WHERE l.standard_id=s.id AND (q.id IS NULL OR q.active IS DISTINCT FROM TRUE)) AS retired_or_broken_links_retained,
 banks.expected_bank,
 CASE WHEN NOT EXISTS(SELECT 1 FROM public.assessment_questions a
    WHERE a.active IS TRUE AND a.standard=banks.expected_bank)
   THEN 'REFERENCE BANK MISSING — REVIEW REQUIRED'
  WHEN banks.base_amendment_review
   THEN 'REFERENCE BANK AVAILABLE — CHECK FIELDWORK AND RECORD AMENDMENT REVIEW'
  ELSE 'REFERENCE BANK AVAILABLE — VERIFY LIVE FIELDWORK COVERAGE'
 END AS next_check
FROM public.internal_audit_standard_catalogue s
JOIN banks ON banks.standard_code=s.standard_code
WHERE s.active IS TRUE
ORDER BY s.standard_code;

